 // Deliver posts the event to the subscriber.
+func Deliver(ctx context.Context, sub Subscriber, ev Event) error {
+	body, err := json.Marshal(ev)
+	if err != nil {
+		return err
+	}
+	// TODO(#412): retry with backoff once the delivery queue lands.
+	_, err = sub.Client.Post(ctx, sub.URL, body)
+	return err
+}
